contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We accept any amount to forward to c.go; the test contract must hold that amount beforehand.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read observable before-values
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the state-changing call sending `amount` wei
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General rule: calling go never changes the owner and leaves contract balance zero
        // (it may revert; in that case owner must still be unchanged and balance unchanged)
        assert((!reverted && ownerAfter == ownerBefore && balAfter == 0) || (reverted && ownerAfter == ownerBefore && balAfter == balBefore));
    }

    receive() external payable {}
}

